<script>
document.addEventListener('DOMContentLoaded', () => {
    const workspace = document.querySelector('[data-course-workspace]'); if (!workspace || workspace.dataset.courseWorkspaceReady) return;
    workspace.dataset.courseWorkspaceReady = 'true';
    const tabs = [...workspace.querySelectorAll('[data-course-tab]')];
    const panels = [...workspace.querySelectorAll('[data-course-panel]')];
    const activate = (name, hash = true) => { if (!panels.some(p => p.dataset.coursePanel === name)) return; tabs.forEach(t => { const active = t.dataset.courseTab === name; t.setAttribute('aria-selected', active ? 'true' : 'false'); t.tabIndex = active ? 0 : -1; }); panels.forEach(p => { p.hidden = p.dataset.coursePanel !== name; }); if (hash) history.replaceState(null, '', `#${name}`); };
    tabs.forEach((tab, index) => { tab.addEventListener('click', () => activate(tab.dataset.courseTab)); tab.addEventListener('keydown', e => { if (!['ArrowRight','ArrowLeft'].includes(e.key)) return; e.preventDefault(); const next = tabs[(index + (e.key === 'ArrowRight' ? -1 : 1) + tabs.length) % tabs.length]; next.focus(); activate(next.dataset.courseTab); requestAnimationFrame(syncHeaderSave); }); });
    const requested = location.hash.slice(1); activate(panels.some(p => p.dataset.coursePanel === requested) ? requested : 'overview', false);
    const headerSave = workspace.querySelector('[data-course-save]');
    const syncHeaderSave = () => { if (headerSave) headerSave.hidden = !['overview','settings'].includes(tabs.find(tab => tab.getAttribute('aria-selected') === 'true')?.dataset.courseTab); };
    tabs.forEach(tab => tab.addEventListener('click', syncHeaderSave)); syncHeaderSave();
    const courseForm = document.getElementById('course-data-form');
    const courseFields = [...workspace.querySelectorAll('[form="course-data-form"]')];
    let dirty = false;
    courseFields.forEach(field => { field.addEventListener('input', () => { dirty = true; }); field.addEventListener('change', () => { dirty = true; }); field.addEventListener('invalid', () => { const panel = field.closest('[data-course-panel]'); if (panel) activate(panel.dataset.coursePanel); }, true); });
    courseForm?.addEventListener('submit', () => { dirty = false; });
    window.addEventListener('beforeunload', event => { if (!dirty) return; event.preventDefault(); event.returnValue = ''; });
    workspace.querySelectorAll('[data-toggle-workspace-create]').forEach(button => button.addEventListener('click', () => { const panel = document.getElementById(button.dataset.toggleWorkspaceCreate); if (panel) { panel.hidden = false; panel.querySelector('input,select,textarea,button')?.focus(); } }));
    workspace.querySelectorAll('[data-close-workspace-create]').forEach(button => button.addEventListener('click', () => { button.closest('.workspace-inline-create').hidden = true; }));
    const scopeInputs = [...workspace.querySelectorAll('input[name="scope"]')]; const context = workspace.querySelector('.workspace-academic-context'); const select = context?.querySelector('select');
    const sync = () => { const general = scopeInputs.find(input => input.checked)?.value === 'general'; if (context) context.hidden = general; if (select) select.disabled = general; }; scopeInputs.forEach(input => input.addEventListener('change', sync)); sync();
});
</script>
@endpush
